source='''from collections import Counter


def transform(grid):
    height, width = len(grid), len(grid[0])
    total = Counter(value for row in grid for value in row)
    threshold = 0.7

    def mode_fraction(values):
        counts = Counter(values)
        value, count = counts.most_common(1)[0]
        return value, count / len(values)

    row_stats = [mode_fraction(row) for row in grid]
    col_stats = [mode_fraction([grid[r][c] for r in range(height)]) for c in range(width)]
    candidates = {value for value, fraction in row_stats if fraction >= threshold} & {
        value for value, fraction in col_stats if fraction >= threshold
    }

    def positions(value, stats):
        return [i for i, (dominant, fraction) in enumerate(stats)
                if dominant == value and fraction >= threshold]

    def regularity(coords):
        if len(coords) < 3:
            return 0
        differences = [b - a for a, b in zip(coords, coords[1:])]
        return Counter(differences).most_common(1)[0][1] / len(differences)

    line_color = max(
        candidates,
        key=lambda value: (
            min(regularity(positions(value, row_stats)), regularity(positions(value, col_stats))),
            len(positions(value, row_stats)) + len(positions(value, col_stats)),
        ),
    )
    remaining_counts = total.copy()
    remaining_counts.pop(line_color, None)
    fill_color = remaining_counts.most_common(1)[0][0]

    row_lines = positions(line_color, row_stats)
    col_lines = positions(line_color, col_stats)
    nodes = [[grid[r][c] for c in col_lines] for r in row_lines]
    active = [(r, c) for r, row in enumerate(nodes) for c, value in enumerate(row)
              if value not in (line_color, fill_color)]
    if not active:
        return []
    r0, r1 = min(r for r, _ in active), max(r for r, _ in active)
    c0, c1 = min(c for _, c in active), max(c for _, c in active)

    output = []
    for r in range(r0, r1):
        output_row = []
        for c in range(c0, c1):
            value = nodes[r][c]
            if value not in (line_color, fill_color) and all(
                nodes[rr][cc] == value for rr, cc in ((r + 1, c), (r, c + 1), (r + 1, c + 1))
            ):
                output_row.append(value)
            else:
                output_row.append(fill_color)
        output.append(output_row)
    return output
'''
